@Composable
fun ListItem(
    modifier: Modifier = Modifier,
    main: String,
    sub: String? = null,
    icon: ImageVector? = null,
    onClick: () -> Unit,
    leadingContent: (@Composable (() -> Unit))? = null,
    trailingContent: (@Composable (() -> Unit))? = null,
    style: TextStyle = MaterialTheme.typography.bodyLarge
) {
